#!/bin/bash
set -e

# Fix: logWhatsAppMessage() never returned a value, so sendWhatsAppTemplate's
# `logResult.error` read threw a TypeError on EVERY send (success or failure).
# That uncaught error crashed the server action mid-request, which is why
# Create Walk-in Visit (and potentially registration) appeared to freeze --
# the request never resolved back to the browser.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

git add lib/whatsapp.js
git commit -m "Fix: logWhatsAppMessage must return a value -- was crashing every WhatsApp send"
git push

echo "Done. Fix deployed."
